SELECT

FROM student s
LEFT JOIN class_info c ON c.id = s.class_id AND c.deleted = 0
WHERE s.deleted = 0

    AND (s.name LIKE CONCAT('%', #{query.keyword}, '%')
    OR s.student_no LIKE CONCAT('%', #{query.keyword}, '%'))


    AND s.class_id = #{query.classId}


    AND s.gender = #{query.gender}


    AND s.status = #{query.status}

ORDER BY s.student_no ASC

SELECT class_id AS classId, COUNT(*) AS total FROM student WHERE deleted = 0 AND class_id IN
#{classId}
GROUP BY class_id
